export const PRODUCT_SCOPE = {
  BEER_ADJ: 'Beer + Adjacencies',
  TOTAL_ABI: 'Total ABI',
} as const;

export const EXPORT_PRODUCT_SCOPE_LABEL = {
  BEER_ADJ: 'Beer + Adj',
  TOTAL_ABI: 'Total ABI',
} as const;

type AppliedProductScope = {
  product_scope?: unknown;
};

export const resolveAppliedProductScope = (
  applied?: AppliedProductScope,
): string | undefined => {
  return typeof applied?.product_scope === 'string'
    ? applied.product_scope
    : undefined;
};

export const isBeerAdjProductScope = (
  productScope: string | undefined,
): boolean => productScope === PRODUCT_SCOPE.BEER_ADJ;

const PRODUCT_SCOPE_FILTER_TYPE = {
  [PRODUCT_SCOPE.BEER_ADJ]: 'BEER+ADJ',
  [PRODUCT_SCOPE.TOTAL_ABI]: 'TotalABI',
} as const;

export const resolveProductScopeFilterType = (
  applied?: AppliedProductScope,
): string => {
  const productScope = resolveAppliedProductScope(applied);

  if (!productScope) return '';

  return (
    PRODUCT_SCOPE_FILTER_TYPE[
      productScope as keyof typeof PRODUCT_SCOPE_FILTER_TYPE
    ] ?? ''
  );
};
